use std::collections::HashMap;
use glam::{Vec2, Vec4};
use rayon::iter::{IntoParallelIterator, ParallelIterator};

use crate::utils::CharacterGlyph;

/// Contains the raw bitmap information about a specific glyph
/// 
/// This is a temporary struct generated by rayon threads.
struct Glyph {
    ch: char,
    metrics: fontdue::Metrics,
    bitmap: Bitmap
}

/// A character bitmap
struct Bitmap {
    data: Vec<u8>,
    width: u32,
    height: u32,
}

struct SdfGrids {
    inside: Vec<Vec2>,
    outside: Vec<Vec2>,
}

impl SdfGrids {
    const FORWARD_OFFSETS: [(i32, i32); 4] = [(-1, 0), (-1, -1), (0, -1), (1, -1)];
    const BACKWARD_OFFSETS: [(i32, i32); 4] = [(1, 0), (1, 1), (0, 1), (-1, 1)];

    pub fn forward_sweep(&mut self, w: i32, h: i32) {
        for y in 0..h {
            for x in 0..w {
                for &(dx, dy) in &SdfGrids::FORWARD_OFFSETS {
                    self.eval_neighbor(w, h, x, y, dx, dy);
                }
            }
        }
    }

    pub fn backward_sweep(&mut self, w: i32, h: i32) {
        for y in (0..h).rev() {
            for x in (0..w).rev() {
                for &(dx, dy) in &SdfGrids::BACKWARD_OFFSETS {
                    self.eval_neighbor(w, h, x, y, dx, dy);
                }
            }
        }
    }

    pub fn merge(self, bitmap: &Bitmap, radius: f32) -> Bitmap {
        let inv_radius = 1.0 / radius;
        let sdf_bitmap: Vec<u8> = self.inside
            .into_iter()
            .enumerate()
            .map(|(i, inside_pt)| {
                let is_inside = bitmap.data[i] > 127;
                let dist = if is_inside {
                    self.outside[i].length_squared().sqrt()
                } else {
                    inside_pt.length_squared().sqrt()
                };

                let normalized = (dist.min(radius) * inv_radius) * 0.5;
                let final_sdf = if is_inside { 0.5 + normalized } else { 0.5 - normalized };

                (final_sdf * 255.0).round() as u8
            })
            .collect();

        Bitmap {
            data: sdf_bitmap,
            width: bitmap.width,
            height: bitmap.height
        }
    }

    fn eval_neighbor(&mut self, w: i32, h: i32, x: i32, y: i32, dx: i32, dy: i32) {
        let nx = x + dx;
        let ny = y + dy;

        if nx >= 0 && nx < w && ny >= 0 && ny < h {
            let curr_idx = (y * w + x) as usize;
            let neigh_idx = (ny * w + nx) as usize;
            let offset_vec = Vec2::new(dx as f32, dy as f32);

            let cand_in = unsafe { *self.inside.get_unchecked(neigh_idx) } + offset_vec;
            if cand_in.length_squared() < self.inside[curr_idx].length_squared() {
                self.inside[curr_idx] = cand_in;
            }

            let cand_out = unsafe { *self.outside.get_unchecked(neigh_idx) } + offset_vec;
            if cand_out.length_squared() < self.outside[curr_idx].length_squared() {
                self.outside[curr_idx] = cand_out;
            }
        }
    }
}

/// Generates an signed-distance field (sdf) from a raw bitmap slice.
struct SdfGenerator;
impl SdfGenerator {
    /// Generates an `SdfGlyph` from a given `bitmap` and `radius`
    pub fn generate(raw_bitmap: &Bitmap, radius: f32) -> Bitmap {
        let padding = radius as u32;
        let sdf_bitmap = SdfGenerator::pad_bitmap(raw_bitmap, padding);
        let mut grids = SdfGenerator::generate_grids(&sdf_bitmap);
    
        let w = sdf_bitmap.width as i32;
        let h = sdf_bitmap.height as i32;

        grids.forward_sweep(w, h);
        grids.backward_sweep(w, h);

        grids.merge(&sdf_bitmap, radius)
    }

    fn pad_bitmap(bitmap: &Bitmap, padding: u32) -> Bitmap {
        let padded_width = bitmap.width + (padding * 2);
        let padded_height = bitmap.height + (padding * 2);
        let total_pixels = (padded_width * padded_height) as usize;

        let mut padded = vec![0u8; total_pixels];
        for r in 0..bitmap.height {
            for c in 0..bitmap.width {
                let src_idx = r * bitmap.width + c;
                let dst_idx = (r + padding) * padded_width + (c + padding);
                padded[dst_idx as usize] = bitmap.data[src_idx as usize];
            }
        }

        Bitmap {
            data: padded,
            width: padded_width,
            height: padded_height
        }
    }

    fn generate_grids(bitmap: &Bitmap) -> SdfGrids {
        let inf = Vec2::splat(9999.0);
        let pixels = (bitmap.width * bitmap.height) as usize;

        let mut inside = vec![inf; pixels];
        let mut outside = vec![inf; pixels];

        for i in 0..pixels {
            if bitmap.data[i] > 127 {
                inside[i] = Vec2::ZERO;
            } else {
                outside[i] = Vec2::ZERO;
            }
        }

        SdfGrids {
            inside, 
            outside,
        }
    }
}

pub enum AtlasType {
    Sdf { radius: f32 },
    BitMap
}

/// Config struct for generating font atlases
pub struct AtlasConfig {
    pub font: fontdue::Font,
    pub size: u32,
    pub scale: f32,
    pub spacing: u32,
    pub ty: AtlasType
}

/// Generate a signed distance field (sdf) font atlas by rasterizing a ttf font
/// 
/// * 'font' - the font containing the glyph metrics
/// * 'size' - the size of the sdf atlas in pixels
/// * 'scale' - the size to rasterize the characters with, in pixels per em unit
/// * 'radius' - the signed distance between extreme values in the sdf atlas
pub fn generate_atlas(config: AtlasConfig) -> (HashMap<char, CharacterGlyph>, Vec<u8>) {
    let characters: Vec<u8> = (32u8..127).collect();
    let sdf_glyphs: Vec<Glyph> = characters
        .into_par_iter()
        .map(|u_char| {
            let ch = u_char as char;
            let (metrics, bitmap) = config.font.rasterize(ch, config.scale);

            let raw_bitmap = Bitmap {
                data: bitmap,
                width: metrics.width as u32,
                height: metrics.height as u32
            };

            let bitmap = match &config.ty {
                AtlasType::Sdf { radius } => {
                    SdfGenerator::generate(&raw_bitmap, *radius)
                }
                AtlasType::BitMap => {
                    raw_bitmap
                }
            };

            Glyph {
                ch, 
                metrics,
                bitmap,
            }
        })
        .collect();

    self::blit_glyphs(sdf_glyphs, config)
}

/// blit character glyphs into a font atlas, and convert metrics into glyph bounds
fn blit_glyphs(glyphs: Vec<Glyph>, config: AtlasConfig) -> (HashMap<char, CharacterGlyph>, Vec<u8>){
    let mut atlas_bitmap = vec![0u8; (config.size * config.size) as usize];
    let mut glyph_table = HashMap::new();

    let mut current_x: u32 = 0;
    let mut current_y: u32 = 0;
    let mut max_row_height: u32 = 0;

    for glyph in glyphs {
        // wrap to next row and add 2px spacing between glyphs
        if current_x + glyph.bitmap.width + config.spacing > config.size {
            current_x = 0;
            current_y += max_row_height + config.spacing;
            max_row_height = 0;
        }
        max_row_height = max_row_height.max(glyph.bitmap.height);

        // blit character sdf bitmap into atlas
        for r in 0..glyph.bitmap.height {
            for c in 0..glyph.bitmap.width {
                let src_idx = (r * glyph.bitmap.width + c) as usize;

                let atlas_x = current_x + c;
                let atlas_y = current_y + r;
                let atlas_idx = (atlas_y * config.size + atlas_x) as usize;

                atlas_bitmap[atlas_idx] = glyph.bitmap.data[src_idx];
            }
        }

        // insert character glyph metrics into glyph table
        let uv_bounds = Vec4::new(
            current_x as f32 / config.size as f32,
            current_y as f32 / config.size as f32,
            glyph.bitmap.width as f32 / config.size as f32,
            glyph.bitmap.height as f32 / config.size as f32,
        );

        let r = match config.ty {
            AtlasType::Sdf { radius } => radius,
            AtlasType::BitMap => { 0.0 }
        };

        let plane_bounds = Vec4::new(
            glyph.metrics.bounds.xmin as f32 - r,
            glyph.metrics.bounds.ymin as f32 - r,
            glyph.metrics.width as f32 + (r * 2.0),
            glyph.metrics.height as f32 + (r * 2.0)
        );

        glyph_table.insert(glyph.ch, CharacterGlyph {
            plane_bounds,
            uv_bounds,
            advance: glyph.metrics.advance_width// + radius
        });

        // advance x coord for next character
        current_x += glyph.bitmap.width + config.spacing;
    }

    (glyph_table, atlas_bitmap)
}